-- Administrative connection only. Fabricated member/session and all finance fixtures roll back.
begin;
create temporary table bulk_test_results(name text,passed boolean);
do $$
declare actor uuid;sid uuid;passkey_sid uuid;a uuid;b uuid;c uuid;t1 uuid;t2 uuid;items jsonb;stale jsonb;r jsonb;before_row jsonb;before_rows jsonb;first_id uuid;last_id uuid;missing uuid:=gen_random_uuid();
begin
 actor:=gen_random_uuid();insert into auth.users(id,email,email_confirmed_at,is_anonymous,created_at,updated_at) values(actor,'mock-bulk@example.invalid',now(),false,now(),now());
 insert into household_private.memberships(user_id,status,role) values(actor,'approved','member');
 sid:=gen_random_uuid();passkey_sid:=sid;insert into auth.sessions(id,user_id,aal) values(sid,actor,'aal1');
 insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'passkey',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 insert into household_private.accounts(name,kind) values('Mock bulk checking','checking') returning id into a;
 insert into household_private.accounts(name,kind) values('Mock bulk savings','savings') returning id into b;
 insert into household_private.categories(name) values('Mock bulk category '||actor) returning id into c;
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint,source,external_id,source_data,notes) values(a,'2026-10-01','Mock bulk out',-100,'mock-bulk-out','monarch','mock-bulk-out','{"tags":[{"name":"Home"},{"name":"Shared"}]}','Mock preserved note') returning id into t1;
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint,tags_override) values(b,'2026-10-02','Mock bulk in',100,'mock-bulk-in',array['Existing']) returning id into t2;
 select jsonb_agg(to_jsonb(t) order by id) into before_rows from household_private.transactions t where id in (t1,t2);
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 r:=public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','category','value',c));
 if r->>'updated_count'<>'2' or exists(select 1 from household_private.transactions where id in (t1,t2) and category_id is distinct from c) then raise exception 'Bulk category failed';end if;
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 r:=public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','category','value',c));
 if r->>'updated_count'<>'0' then raise exception 'No-op category rewrote rows';end if;
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','review','value','reviewed'));
 if exists(select 1 from household_private.transactions where id in (t1,t2) and (review_status<>'reviewed' or reviewed_at is null or reviewed_by<>actor)) then raise exception 'Review metadata missing';end if;
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','attention','value',true));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 r:=public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','add_tag','value','shared'));
 if r->>'updated_count'<>'1' or (select tags_override from household_private.transactions where id=t1) is not null or (select tags_override from household_private.transactions where id=t2) is distinct from array['Existing','shared'] then raise exception 'Tag merge/dedup failed';end if;
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','add_tag','value','New'));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','remove_tag','value','SHARED'));
 if (select tags_override from household_private.transactions where id=t1) is distinct from array['Home','New'] or (select tags_override from household_private.transactions where id=t2) is distinct from array['Existing','New'] then raise exception 'Tag removal lost other labels';end if;
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','category','value',null));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','review','value','unreviewed'));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','attention','value',false));
 if exists(select 1 from household_private.transactions where id in (t1,t2) and (category_id is not null or review_status<>'unreviewed' or reviewed_at is not null or reviewed_by is not null or needs_attention)) then raise exception 'Clearing category/review/attention failed';end if;
 select to_jsonb(t) into before_row from household_private.transactions t where id=t1;
 if before_row->>'notes'<>'Mock preserved note' or before_row->>'description'<>'Mock bulk out' or before_row->>'account_id'<>a::text or before_row->>'amount_minor'<>'-100' or before_row->>'external_id'<>'mock-bulk-out' or before_row->'source_data'->'tags'->1->>'name'<>'Shared' then raise exception 'Bulk changed individual/source fields';end if;
 insert into bulk_test_results values('category/review/attention toggles, no-op counts and case-insensitive tag merge/removal preserve other fields',true);
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 select jsonb_agg(to_jsonb(t) order by id) into before_rows from household_private.transactions t where id in (t1,t2);
 stale:=jsonb_set(items,'{1,revision}','999999');
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',stale,'action','attention','value',true));raise exception 'Stale batch accepted';exception when serialization_failure then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items||jsonb_build_array(jsonb_build_object('id',missing,'revision',1)),'action','attention','value',true));raise exception 'Missing selection accepted';exception when no_data_found then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items||jsonb_build_array(items->0),'action','attention','value',true));raise exception 'Duplicate selection accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items','[]'::jsonb,'action','trash'));raise exception 'Empty selection accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',(select jsonb_agg(items->0) from generate_series(1,51)),'action','trash'));raise exception 'Overlimit selection accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','category','value',missing));raise exception 'Missing category accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','attention','value','true'));raise exception 'String boolean accepted';exception when invalid_parameter_value then null;end;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','description','value','Forbidden'));raise exception 'Forbidden bulk field accepted';exception when invalid_parameter_value then null;end;
 if (select jsonb_agg(to_jsonb(t) order by id) from household_private.transactions t where id in (t1,t2))<>before_rows then raise exception 'Failed preflight changed some rows';end if;
 -- A late validation failure must also roll back a change to an earlier row.
 select id into first_id from household_private.transactions where id in (t1,t2) order by id limit 1;
 select id into last_id from household_private.transactions where id in (t1,t2) order by id desc limit 1;
 update household_private.transactions set tags_override=(select array_agg('Mock tag '||n) from generate_series(1,20) n) where id=last_id;
 select jsonb_agg(to_jsonb(t) order by id) into before_rows from household_private.transactions t where id in (t1,t2);
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','add_tag','value','Overflow'));raise exception 'Tag limit accepted';exception when invalid_parameter_value then null;end;
 if (select jsonb_agg(to_jsonb(t) order by id) from household_private.transactions t where id in (t1,t2))<>before_rows then raise exception 'Late failure partially applied a batch';end if;
 insert into bulk_test_results values('invalid, stale, missing, duplicate and oversized batches reject atomically, including late tag-limit failure',true);
 -- Linked transfers allow metadata changes but block whole-batch Trash.
 r:=public.household_v1('get_transaction_detail',jsonb_build_object('id',t1));
 before_row:=public.household_v1('get_transaction_detail',jsonb_build_object('id',t2));
 perform public.household_v1('link_transfer',jsonb_build_object('id',t1,'revision',r->'revision','peer_id',t2,'peer_revision',before_row->'revision','flow_type','transfer'));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','category','value',c));
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','trash'));raise exception 'Linked transfer bulk Trash accepted';exception when serialization_failure then null;end;
 if exists(select 1 from household_private.transactions where id in (t1,t2) and deleted_at is not null) then raise exception 'Linked batch partially trashed';end if;
 r:=public.household_v1('get_transaction_detail',jsonb_build_object('id',t1));
 perform public.household_v1('unlink_transfer',jsonb_build_object('id',t1,'revision',r->'revision','peer_id',t2,'peer_revision',r->'transfer_peer'->'revision'));
 insert into household_private.receipts(transaction_id,object_path,filename,mime_type,byte_size,sha256,state,created_by) values(t1,t1::text||'/mock-bulk','mock.pdf','application/pdf',12,repeat('c',64),'ready',actor);
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','trash'));
 if exists(select 1 from household_private.transactions where id in (t1,t2) and deleted_at is null) or not exists(select 1 from household_private.receipts where transaction_id=t1 and removed_at is null) then raise exception 'Bulk Trash lost records/receipt';end if;
 select jsonb_agg(jsonb_build_object('id',id,'revision',revision)) into items from household_private.transactions where id in (t1,t2);
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','review','value','reviewed'));raise exception 'Edited Trash records';exception when serialization_failure then null;end;
 perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','restore'));
 if exists(select 1 from household_private.transactions where id in (t1,t2) and deleted_at is not null) or (select notes<>'Mock preserved note' from household_private.transactions where id=t1) then raise exception 'Bulk Restore lost notes';end if;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','restore'));raise exception 'Restore replay accepted';exception when serialization_failure then null;end;
 insert into bulk_test_results values('linked metadata updates, all-or-nothing Trash guard, recoverable bulk Trash/Restore and receipt preservation',true);
 sid:=gen_random_uuid();insert into auth.sessions(id,user_id,aal) values(sid,actor,'aal1');
 insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'otp',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','trash'));raise exception 'OTP bulk action accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',passkey_sid,'role','authenticated')::text,true);
 update household_private.memberships set status='removed' where user_id=actor;
 begin perform public.household_v1('bulk_update_transactions',jsonb_build_object('items',items,'action','trash'));raise exception 'Removed member bulk action accepted';exception when insufficient_privilege then null;end;
 if has_function_privilege('authenticated','household_private.bulk_transactions(jsonb)','EXECUTE') or has_function_privilege('anon','household_private.bulk_transactions(jsonb)','EXECUTE') then raise exception 'Private bulk helper exposed';end if;
 insert into bulk_test_results values('approved live-passkey membership is required and private helper privileges remain revoked',true);
end $$;
select * from bulk_test_results order by name;
rollback;
